import React from 'react';
import { Nav, Badge } from 'react-bootstrap';
import { Link, useLocation } from 'react-router-dom';
import { getUserRole } from '../../utils/auth';
import { USER_ROLES } from '../../utils/constants';

const Sidebar = () => {
  const location = useLocation();
  const userRole = getUserRole();

  const isActive = (path) => location.pathname === path;

  const MenuItem = ({ to, icon, children, badge, isActive: active }) => (
    <Nav.Link 
      as={Link} 
      to={to} 
      className={`d-flex align-items-center justify-content-between transition-all ${active ? 'active' : ''}`}
    >
      <div className="d-flex align-items-center">
        <i className={`${icon} me-3`}></i>
        <span className="fw-medium">{children}</span>
      </div>
      {badge && (
        <Badge bg="primary" pill className="ms-auto">
          {badge}
        </Badge>
      )}
    </Nav.Link>
  );

  const renderUserMenu = () => (
    <div className="fade-in-left">
      <div className="px-3 py-2 mb-3">
        <h6 className="text-primary fw-bold mb-0 d-flex align-items-center">
          <i className="fas fa-user-circle me-2"></i>
          Menu User
        </h6>
        <small className="text-muted">Kelola booking ruangan Anda</small>
      </div>
      
      <MenuItem 
        to="/user/dashboard" 
        icon="fas fa-tachometer-alt" 
        isActive={isActive('/user/dashboard')}
      >
        Dashboard
      </MenuItem>
      
      <MenuItem 
        to="/user/booking" 
        icon="fas fa-plus-circle" 
        isActive={isActive('/user/booking')}
      >
        Buat Booking
      </MenuItem>
      
      <MenuItem 
        to="/user/mybookings" 
        icon="fas fa-list-ul" 
        isActive={isActive('/user/mybookings')}
        badge="3"
      >
        Booking Saya
      </MenuItem>
    </div>
  );

  const renderAdminMenu = () => (
    <div className="fade-in-left">
      <div className="px-3 py-2 mb-3">
        <h6 className="text-danger fw-bold mb-0 d-flex align-items-center">
          <i className="fas fa-crown me-2"></i>
          Admin Panel
        </h6>
        <small className="text-muted">Kelola sistem secara menyeluruh</small>
      </div>
      
      <MenuItem 
        to="/admin/dashboard" 
        icon="fas fa-chart-line" 
        isActive={isActive('/admin/dashboard')}
      >
        Dashboard Admin
      </MenuItem>
      
      <MenuItem 
        to="/admin/bookings" 
        icon="fas fa-calendar-check" 
        isActive={isActive('/admin/bookings')}
        badge="12"
      >
        Kelola Booking
      </MenuItem>
      
      <MenuItem 
        to="/admin/zoom" 
        icon="fas fa-video" 
        isActive={isActive('/admin/zoom')}
      >
        Kelola Zoom
      </MenuItem>
    </div>
  );

  const renderLogistikMenu = () => (
    <div className="fade-in-left">
      <div className="px-3 py-2 mb-3">
        <h6 className="text-warning fw-bold mb-0 d-flex align-items-center">
          <i className="fas fa-tools me-2"></i>
          Panel Logistik
        </h6>
        <small className="text-muted">Kelola ruangan dan fasilitas</small>
      </div>
      
      <MenuItem 
        to="/logistik/dashboard" 
        icon="fas fa-chart-bar" 
        isActive={isActive('/logistik/dashboard')}
      >
        Dashboard Logistik
      </MenuItem>
      
      <MenuItem 
        to="/logistik/bookings" 
        icon="fas fa-door-open" 
        isActive={isActive('/logistik/bookings')}
        badge="5"
      >
        Booking Ruangan
      </MenuItem>
      
      <MenuItem 
        to="/logistik/rooms" 
        icon="fas fa-building" 
        isActive={isActive('/logistik/rooms')}
      >
        Kelola Ruangan
      </MenuItem>
    </div>
  );

  return (
    <div className="sidebar min-vh-100 p-0">
      <div className="p-4">
        {/* Role Indicator */}
        <div className="text-center mb-4">
          <div className="d-inline-flex align-items-center justify-content-center bg-gradient-primary rounded-circle mb-2" style={{ width: '60px', height: '60px' }}>
            {userRole === USER_ROLES.USER && <i className="fas fa-user text-white fs-4"></i>}
            {userRole === USER_ROLES.ADMIN && <i className="fas fa-crown text-white fs-4"></i>}
            {userRole === USER_ROLES.LOGISTIK && <i className="fas fa-tools text-white fs-4"></i>}
          </div>
          <div className="fw-bold text-primary">
            {userRole === USER_ROLES.USER && 'User'}
            {userRole === USER_ROLES.ADMIN && 'Administrator'}
            {userRole === USER_ROLES.LOGISTIK && 'Staff Logistik'}
          </div>
          <small className="text-muted">BRIRoom System</small>
        </div>

        {/* Navigation Menu */}
        <Nav className="flex-column">
          {userRole === USER_ROLES.USER && renderUserMenu()}
          {userRole === USER_ROLES.ADMIN && renderAdminMenu()}
          {userRole === USER_ROLES.LOGISTIK && renderLogistikMenu()}
        </Nav>

        {/* Quick Actions */}
        <div className="mt-5 pt-4 border-top">
          <h6 className="px-3 text-muted fw-bold mb-3 small">QUICK ACTIONS</h6>
          <Nav className="flex-column">
            <Nav.Link className="d-flex align-items-center text-muted small transition-all">
              <i className="fas fa-question-circle me-3"></i>
              Bantuan
            </Nav.Link>
            <Nav.Link className="d-flex align-items-center text-muted small transition-all">
              <i className="fas fa-book me-3"></i>
              Panduan
            </Nav.Link>
            <Nav.Link className="d-flex align-items-center text-muted small transition-all">
              <i className="fas fa-phone me-3"></i>
              Kontak Support
            </Nav.Link>
          </Nav>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
